  use Veltrion\Services\AI\Contracts\AIProviderInterface; use Veltrion\Services\AI\DTOs\AIRequest; use Veltrion\Services\AI\DTOs\AIResponse; class GeminiProvider implements AIProviderInterface { private string $apiKey; private string $defaultModel; public function __construct(string $apiKey = '', string $defaultModel = 'gemini-2.5-flash') { $this->apiKey = $apiKey ?: getenv('GEMINI_API_KEY') ?: ''; $this->defaultModel = $defaultModel; } public function getName(): string { return 'Google Gemini API'; } public function isAvailable(): bool { return !empty($this->apiKey); } public function listModels(): array { return ['gemini-2.5-flash', 'gemini-2.5-pro']; } public function generate(AIRequest $request): AIResponse { if (!$this->isAvailable()) { return new AIResponse( "", $this->getName(), $this->defaultModel, false, "GEMINI_API_KEY no está configurada en .env" ); } $model = $request->getModel() ?: $this->defaultModel; $url = "https://generativelanguage.googleapis.com/v1beta/models/{$model}:generateContent?key={$this->apiKey}"; $payload = [ 'contents' => [ [ 'parts' => [ ['text' => ($request->getContext() ? "Context:\n{$request->getContext()}\n\n" : "") . $request->getPrompt()] ] ] ] ]; $ch = curl_init($url); curl_setopt($ch, CURLOPT_RETURNTRANSFER, true); curl_setopt($ch, CURLOPT_POST, true); curl_setopt($ch, CURLOPT_HTTPHEADER, ['Content-Type: application/json']); curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($payload)); curl_setopt($ch, CURLOPT_TIMEOUT, 30); $res = curl_exec($ch); $code = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch); if ($code === 200 && $res) { $json = json_decode($res, true); $text = $json['candidates'][0]['content']['parts'][0]['text'] ?? ''; return new AIResponse($text, $this->getName(), $model, true); } return new AIResponse("", $this->getName(), $model, false, "Error HTTP Gemini: {$code}"); } } 